384: /* ------------------------------ input ------------------------------ */
385: const keys = new Set();
386: const touchAxes = [0, 0];          // analog joystick output, -1..1
387: const joysticks = [];
388: const pointerOwners = new Map();
389: const PLAYER_KEYS = [
390:   { left: ['KeyA'], right: ['KeyD'], jump: ['KeyW'], throw: ['Space'] },
391:   { left: ['ArrowLeft'], right: ['ArrowRight'], jump: ['ArrowUp'], throw: ['Enter', 'Numpad0'] },
392: ];
393: function hasAny(code, list) { return list.includes(code); }
394: function playerForKey(code) {
395:   for (let i = 0; i < 2; i++) {
396:     const m = PLAYER_KEYS[i];
397:     if (hasAny(code, m.left) || hasAny(code, m.right) || hasAny(code, m.jump) || hasAny(code, m.throw)) return { i, action: hasAny(code, m.left) ? 'left' : hasAny(code, m.right) ? 'right' : hasAny(code, m.jump) ? 'jump' : 'throw' };
398:   }
399:   return null;
400: }
401: function isModalOpen() {
402:   return !el.screenArcade.classList.contains('hidden') || !el.screenHow.classList.contains('hidden');
403: }
404: function getInputDir(p) {
405:   if (p.ai) return p.aiMove;
406:   let dir = 0;
407:   if (p.idx === 0) {
408:     if (keys.has('KeyA')) dir--;
409:     if (keys.has('KeyD')) dir++;
410:   } else {
411:     if (keys.has('ArrowLeft')) dir--;
412:     if (keys.has('ArrowRight')) dir++;
413:   }
414:   const axis = touchAxes[p.idx];
415:   if (axis) dir += axis;
416:   return clamp(dir, -1, 1);
417: }
418: function doJump(p, strength = 1) {
419:   if (!p || p.ko) return;
420:   p.vy = -jumpSpeedFor() * strength;
421:   p.onGround = false;
422:   p.coyote = 0;
423:   p.jumpBuffer = 0;
424:   if (p.wasGround) { dust(p.x, p.y, 4); sfx.jump(); }
425:   else {
426:     dust(p.x, p.y - 15 * S, 4);
427:     burst(p.x, p.y - 20 * S, P_COLORS[p.idx], 6, 0.5, 'dot');
428:     sfx.jump();
429:   }
430: }
431: function queueJump(p) {
432:   if (!p || p.ko) return;
433:   if (state !== 'play' && state !== 'title') return;
434:   p.jumpBuffer = 0.13;
435: }
436: function requestThrow(p) {
437:   if (!p || p.ko) return;
438:   if (state !== 'play' && state !== 'title') return;
439:   beginThrow(p);
440: }
441: function releaseThrowInput(p) {
442:   if (!p) return;
443:   if (p.charging) releaseThrow(p);
444: }
