446: function onKeyDown(e) {
447:   ensureAudio();
448:   if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Enter'].includes(e.code)) e.preventDefault();
449:   if (e.repeat) return;
450:   keys.add(e.code);
451: 
452:   if (isModalOpen()) {
453:     if (e.code === 'Escape') {
454:       if (!el.screenHow.classList.contains('hidden')) closeHow();
455:       else closeArcade();
456:     }
457:     return;
458:   }
459:   if (state === 'title') {
460:     if (e.code === 'Enter' || e.code === 'Space') { sfx.ui(); newMatch('2p', titleChars); }
461:     return;
462:   }
463:   if (state === 'matchEnd') {
464:     if (endShown && (e.code === 'Enter' || e.code === 'Space')) rematch();
465:     return;
466:   }
467:   if (e.code === 'Escape') {
468:     if (paused) pauseGame(false);
469:     else pauseGame(true);
470:     return;
471:   }
472:   if (e.code === 'KeyM') { setMuted(!profile.muted); return; }
473:   if (paused) return;
474: 
475:   const pk = playerForKey(e.code);
476:   if (!pk) return;
477:   const p = players[pk.i];
478:   if (!p) return;
479:   if (pk.action === 'jump') queueJump(p);
480:   else if (pk.action === 'throw' && state === 'play') requestThrow(p);
481: }
482: 
483: function onKeyUp(e) {
484:   keys.delete(e.code);
485:   const pk = playerForKey(e.code);
486:   if (!pk) return;
487:   const p = players[pk.i];
488:   if (!p) return;
489:   if (pk.action === 'throw') releaseThrowInput(p);
490:   if (pk.action === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
491: }
