493: function bindTouch() {
494:   document.querySelectorAll('.tbtn[data-act]').forEach(btn => {
495:     const pad = btn.closest('.pad');
496:     const pIdx = Number(pad.dataset.player);
497:     const act = btn.dataset.act;
498:     const down = e => {
499:       e.preventDefault();
500:       ensureAudio();
501:       if (state !== 'play' && state !== 'title') return;
502:       if (paused) return;
503:       btn.classList.add('pressed');
504:       pointerOwners.set(e.pointerId, { pIdx, act, btn });
505:       try { btn.setPointerCapture?.(e.pointerId); } catch {}
506:       const p = players[pIdx];
507:       if (!p) return;
508:       if (act === 'jump') queueJump(p);
509:       if (act === 'throw') {
510:         const moving = Math.abs(getInputDir(p)) > 0.15;
511:         requestThrow(p);
512:         if (!moving) setTimeout(() => releaseThrowInput(p), 90);
513:       }
514:     };
515:     const up = e => {
516:       const own = pointerOwners.get(e.pointerId);
517:       if (!own || own.pIdx !== pIdx) return;
518:       pointerOwners.delete(e.pointerId);
519:       btn.classList.remove('pressed');
520:       const p = players[pIdx];
521:       if (!p) return;
522:       if (act === 'throw') releaseThrowInput(p);
523:       if (act === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
524:     };
525:     btn.addEventListener('pointerdown', down);
526:     btn.addEventListener('pointerup', up);
527:     btn.addEventListener('pointercancel', up);
528:     btn.addEventListener('lostpointercapture', up);
529:     btn.addEventListener('contextmenu', e => e.preventDefault());
530:   });
531: }
