533: /* ------------------------------ virtual joysticks ------------------------------ */
534: function bindJoysticks() {
535:   joysticks.length = 0;
536:   document.querySelectorAll('#touch .joystick').forEach(joyEl => {
537:     const pad = joyEl.closest('.pad');
538:     const pIdx = Number(pad.dataset.player);
539:     const base = joyEl.querySelector('.stick-base');
540:     const knob = joyEl.querySelector('.stick-knob');
541:     const j = { el: joyEl, knob, pIdx, pointerId: null, max: 1, jumpLatch: false };
542:     joysticks.push(j);
543: 
544:     const centerOf = () => {
545:       const r = base.getBoundingClientRect();
546:       const bounds = joyEl.getBoundingClientRect();
547:       const x = r.left + r.width / 2;
548:       const y = r.top + r.height / 2;
549:       // Anchor the knob to the base's measured center, not an assumed 50% of
550:       // its parent. This stays centered if the base and joystick ever diverge.
551:       knob.style.left = `${((x - bounds.left) / bounds.width) * 100}%`;
552:       knob.style.top = `${((y - bounds.top) / bounds.height) * 100}%`;
553:       j.max = Math.max(1, Math.min(r.width, r.height) * 0.3);
554:       return { x, y };
555:     };
556:     j.centerKnob = () => {
557:       centerOf();
558:       knob.style.transform = 'translate(-50%, -50%)';
559:     };
560:     const setAxis = (dx, dy) => {
561:       const raw = Math.hypot(dx, dy);
562:       const scale = raw > j.max ? j.max / raw : 1;
563:       const kx = dx * scale, ky = dy * scale;
564:       knob.style.transform = `translate(-50%, -50%) translate(${kx}px, ${ky}px)`;
565:       const x = clamp(kx / j.max, -1, 1);
566:       const dead = 0.16;
567:       touchAxes[pIdx] = Math.sign(x) * clamp((Math.abs(x) - dead) / (1 - dead), 0, 1);
568:       // drop through platforms on downward flick
569:       if (ky > j.max * 0.5) {
570:         const pp = players[pIdx];
571:         if (pp) {
572:           pp.dropThrough = 0.25;
573:           if (pp.onGround && pp.y < floorY - 1) { pp.vy = 120 * S; pp.onGround = false; }
574:         }
575:       }
576:       // jump on upward flick
577:       if (ky < -j.max * 0.5 && !j.jumpLatch) {
578:         j.jumpLatch = true;
579:         const p = players[pIdx];
580:         if (p) queueJump(p);
581:       }
582:       if (ky > -j.max * 0.25) j.jumpLatch = false;
583:     };
584:     const release = e => {
585:       if (j.pointerId === null) return;
586:       if (e && e.pointerId !== undefined && e.pointerId !== j.pointerId) return;
587:       const p = players[pIdx];
588:       if (p && p.charging) {
589:         releaseThrow(p);
590:         p.needsMove = true;
591:       }
592:       j.pointerId = null;
593:       j.jumpLatch = false;
594:       touchAxes[pIdx] = 0;
595:       joyEl.classList.remove('active');
596:       j.centerKnob();
597:     };
598:     const canUse = () => (state === 'play' || state === 'title') && !paused;
599: 
600:     joyEl.addEventListener('pointerdown', e => {
601:       e.preventDefault();
602:       ensureAudio();
603:       if (!canUse() || j.pointerId !== null) return;
604:       j.pointerId = e.pointerId;
605:       joyEl.classList.add('active');
606:       try { joyEl.setPointerCapture(e.pointerId); } catch {}
607:       const c = centerOf();
608:       setAxis(e.clientX - c.x, e.clientY - c.y);
609:     });
610:     joyEl.addEventListener('pointermove', e => {
611:       if (j.pointerId !== e.pointerId) return;
612:       e.preventDefault();
613:       const c = centerOf();
614:       setAxis(e.clientX - c.x, e.clientY - c.y);
615:     });
616:     joyEl.addEventListener('pointerup', release);
617:     joyEl.addEventListener('pointercancel', release);
618:     joyEl.addEventListener('lostpointercapture', release);
619:     joyEl.addEventListener('contextmenu', e => e.preventDefault());
620:   });
621: }
622: 
623: function resetJoysticks() {
624:   touchAxes[0] = 0;
625:   touchAxes[1] = 0;
626:   for (const j of joysticks) {
627:     j.pointerId = null;
628:     j.jumpLatch = false;
629:     j.centerKnob();
630:   }
631:   pointerOwners.clear();
632:   document.querySelectorAll('.tbtn.pressed').forEach(b => b.classList.remove('pressed'));
633: }
