635: /* ------------------------------ player update ------------------------------ */
636: function updatePlayer(p, dt) {
637:   if (!p) return;
638:   // timers
639:   p.throwCd = Math.max(0, p.throwCd - dt);
640:   p.throwAnim = Math.max(0, p.throwAnim - dt);
641:   p.catchAnim = Math.max(0, p.catchAnim - dt);
642:   p.invuln = Math.max(0, p.invuln - dt);
643:   p.hitstun = Math.max(0, p.hitstun - dt);
644:   p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
645:   p.dropThrough = Math.max(0, (p.dropThrough || 0) - dt);
646:   p.blinkTimer -= dt;
647:   if (p.blinkTimer <= 0) { p.blink = 0.11; p.blinkTimer = rand(2.2, 4.8); }
648:   p.blink = Math.max(0, p.blink - dt);
649:   if (p.ko) {
650:     p.koT += dt;
651:     p.vy += gravityFor() * dt;
652:     p.x += p.vx * dt;
653:     p.y += p.vy * dt;
654:     p.vx *= Math.pow(0.2, dt);
655:     if (p.y > floorY) { p.y = floorY; p.vy = 0; p.vx *= 0.7; }
656:     p.x = clamp(p.x, arena.left + 22 * S, arena.right - 22 * S);
657:     p.onGround = p.y >= floorY - 0.5;
658:     return;
659:   }
660: 
661:   if (p.ai && (state === 'play' || state === 'title')) updateAI(p, dt);
662: 
663:   const canControl = state === 'play' && !paused;
664:   let dir = canControl ? getInputDir(p) : 0;
665:   if (p.hitstun > 0) dir = 0;
666: 
667:   // drop through platforms on down input
668:   if (state === 'play' && canControl && !p.ai) {
669:     const downHeld = (p.idx === 0 && keys.has('KeyS')) || (p.idx === 1 && keys.has('ArrowDown'));
670:     if (downHeld) {
671:       p.dropThrough = 0.2;
672:       if (p.onGround && p.y < floorY - 1) { p.vy = 120 * S; p.onGround = false; }
673:     }
674:   }
675: 
676:   // auto-charge / auto-fire for human players
677:   if (state === 'play' && canControl && !p.ai && !p.ko && p.hitstun <= 0) {
678:     const moving = Math.abs(dir) > 0.15;
679:     if (moving) {
680:       if (p.needsMove) p.needsMove = false;
681:       if (!p.charging && p.throwCd <= 0 && !p.needsMove) beginThrow(p);
682:     }
683:   }
684: 
685:   // jump buffering
686:   if (p.jumpBuffer > 0 && canControl) {
687:     if (p.onGround || p.coyote > 0) { p.wasGround = true; doJump(p, 1); p.jumpsLeft = 1; }
688:     else if (p.jumpsLeft > 0) { p.jumpsLeft--; p.wasGround = false; doJump(p, 0.88); }
689:   }
690: 
691:   const maxSp = runSpeedFor() * (p.charging ? 0.58 : 1) * (p.hitstun > 0 ? 0.5 : 1);
692:   if (dir !== 0) {
693:     p.facing = Math.sign(dir) || p.facing;
694:     p.vx += dir * 2900 * S * dt;
695:     p.vx = clamp(p.vx, -maxSp, maxSp);
696:   } else {
697:     p.vx *= Math.pow(0.0009, dt);
698:     if (Math.abs(p.vx) < 4 * S) p.vx = 0;
699:   }
700: 
701:   if (p.charging && canControl) {
702:     p.charge = Math.min(1, p.charge + dt / 1.24);
703:     p.chargeFx = (p.chargeFx || 0) - dt;
704:     if (p.chargeFx <= 0) {
705:       p.chargeFx = 0.07;
706:       const h = handPoint(p);
707:       addParticle({
708:         x: h.x + rand(-14, 14) * S, y: h.y + rand(-14, 14) * S,
709:         vx: rand(-30, 30) * S, vy: rand(-70, -10) * S,
710:         life: rand(0.2, 0.45), size: rand(2, 4.5) * S,
711:         color: P_COLORS[p.idx], kind: 'dot', grav: -60 * S, drag: 0.92,
712:       });
713:     }
714:   } else {
715:     p.charge = 0;
716:   }
717: 
718:   // physics
719:   p.wasGround = p.onGround;
720:   const prevY = p.y;
721:   p.vy += gravityFor() * dt;
722:   p.vy = Math.min(p.vy, 1900 * S);
723:   p.x += p.vx * dt;
724:   p.y += p.vy * dt;
725:   p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
726: 
727:   p.onGround = false;
728:   p.platform = null;
729:   if (p.vy >= 0 && (p.dropThrough || 0) <= 0) {
730:     for (const pl of platforms) {
731:       if (prevY <= pl.y + 2 && p.y >= pl.y && p.y <= pl.y + pl.h + 30 * S &&
732:           p.x + 14 * S > pl.x + 3 && p.x - 14 * S < pl.x + pl.w - 3) {
733:         p.y = pl.y;
734:         p.vy = 0;
735:         p.onGround = true;
736:         p.jumpsLeft = 1;
737:         p.platform = pl;
738:         break;
739:       }
740:     }
741:   }
742:   if (p.y >= floorY) {
743:     p.y = floorY;
744:     p.vy = 0;
745:     p.onGround = true;
746:     p.jumpsLeft = 1;
747:     p.platform = null;
748:   }
749:   if (p.onGround) p.coyote = 0.1;
750:   else p.coyote = Math.max(0, p.coyote - dt);
751: 
752:   // carry on moving platforms
753:   if (p.onGround && p.platform) {
754:     p.x += (p.platform.vx || 0) * dt;
755:     p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
756:   }
757: 
758:   if (p.onGround && !p.wasGround && p.vy === 0) {
759:     dust(p.x, p.y, 5);
760:     if (Math.abs(p.vx) > 40 * S || state === 'play') sfx.land();
761:   }
762: 
763:   p.runPhase += Math.abs(p.vx) * dt * 0.033;
764: }
765: 
766: function updateAI(p, dt) {
767:   const opp = getOpponent(p);
768:   if (!opp) return;
769:   p.aiTimer -= dt;
770:   p.aiStrafeTimer -= dt;
771:   p.aiJumpCd -= dt;
772: 
773:   if (state === 'title') {
774:     p.demoT += dt;
775:     p.demoThrow -= dt;
776:     const home = arena.left + (arena.right - arena.left) * (p.idx === 0 ? 0.13 : 0.87);
777:     const tx = home + Math.sin(p.demoT * 0.55 + p.idx * 2.1) * 70 * S;
778:     p.aiMove = clamp((tx - p.x) / (70 * S), -1, 1);
779:     if (p.charging) {
780:       p.aiCharge += dt;
781:       if (p.aiCharge > p.aiHold) releaseThrow(p);
782:     } else if (p.demoThrow <= 0 && p.throwCd <= 0 && balls.length < 3) {
783:       beginThrow(p);
784:       p.aiHold = rand(0.35, 0.85);
785:       p.aiCharge = 0;
786:       p.demoThrow = rand(2.4, 4.4);
787:     }
788:     if (p.onGround && Math.random() < dt * 0.18) p.jumpBuffer = 0.1;
789:     return;
790:   }
791: 
792:   if (p.aiStrafeTimer <= 0) {
793:     p.aiStrafe = pick([-1, 0, 1]);
794:     p.aiStrafeTimer = rand(0.7, 1.7);
795:   }
796:   const dx = opp.x - p.x;
797:   const adx = Math.abs(dx);
798:   let move = 0;
799:   if (adx > 460 * S) move = Math.sign(dx);
800:   else if (adx < 200 * S) move = -Math.sign(dx);
801:   else move = p.aiStrafe * 0.65;
802:   if (p.x < arena.left + 70 * S) move = 1;
803:   if (p.x > arena.right - 70 * S) move = -1;
804:   p.aiMove = clamp(move, -1, 1);
805: 
806:   const threat = balls.find(b => !b.dead && b.owner !== p.idx &&
807:     dist(b.x, b.y, p.x, p.y - 42 * S) < 235 * S &&
808:     (b.vx * (p.x - b.x) + b.vy * (p.y - 42 * S - b.y)) > 0);
809:   if (threat && p.onGround && p.aiJumpCd <= 0) {
810:     p.jumpBuffer = 0.12;
811:     p.aiJumpCd = rand(0.9, 1.8);
