384: /* ------------------------------ input ------------------------------ */
385: const keys = new Set();
386: const touchAxes = [0, 0];          // analog joystick output, -1..1
387: const joysticks = [];
388: const pointerOwners = new Map();
389: const PLAYER_KEYS = [
390:   { left: ['KeyA'], right: ['KeyD'], jump: ['KeyW'], throw: ['Space'] },
391:   { left: ['ArrowLeft'], right: ['ArrowRight'], jump: ['ArrowUp'], throw: ['Enter', 'Numpad0'] },
392: ];
393: function hasAny(code, list) { return list.includes(code); }
394: function playerForKey(code) {
395:   for (let i = 0; i < 2; i++) {
396:     const m = PLAYER_KEYS[i];
397:     if (hasAny(code, m.left) || hasAny(code, m.right) || hasAny(code, m.jump) || hasAny(code, m.throw)) return { i, action: hasAny(code, m.left) ? 'left' : hasAny(code, m.right) ? 'right' : hasAny(code, m.jump) ? 'jump' : 'throw' };
398:   }
399:   return null;
400: }
401: function isModalOpen() {
402:   return !el.screenArcade.classList.contains('hidden') || !el.screenHow.classList.contains('hidden');
403: }
404: function getInputDir(p) {
405:   if (p.ai) return p.aiMove;
406:   let dir = 0;
407:   if (p.idx === 0) {
408:     if (keys.has('KeyA')) dir--;
409:     if (keys.has('KeyD')) dir++;
410:   } else {
411:     if (keys.has('ArrowLeft')) dir--;
412:     if (keys.has('ArrowRight')) dir++;
413:   }
414:   const axis = touchAxes[p.idx];
415:   if (axis) dir += axis;
416:   return clamp(dir, -1, 1);
417: }
418: function doJump(p, strength = 1) {
419:   if (!p || p.ko) return;
420:   p.vy = -jumpSpeedFor() * strength;
421:   p.onGround = false;
422:   p.coyote = 0;
423:   p.jumpBuffer = 0;
424:   if (p.wasGround) { dust(p.x, p.y, 4); sfx.jump(); }
425:   else {
426:     dust(p.x, p.y - 15 * S, 4);
427:     burst(p.x, p.y - 20 * S, P_COLORS[p.idx], 6, 0.5, 'dot');
428:     sfx.jump();
429:   }
430: }
431: function queueJump(p) {
432:   if (!p || p.ko) return;
433:   if (state !== 'play' && state !== 'title') return;
434:   p.jumpBuffer = 0.13;
435: }
436: function requestThrow(p) {
437:   if (!p || p.ko) return;
438:   if (state !== 'play' && state !== 'title') return;
439:   beginThrow(p);
440: }
441: function releaseThrowInput(p) {
442:   if (!p) return;
443:   if (p.charging) releaseThrow(p);
444: }
445: 
446: function onKeyDown(e) {
447:   ensureAudio();
448:   if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Enter'].includes(e.code)) e.preventDefault();
449:   if (e.repeat) return;
450:   keys.add(e.code);
451: 
452:   if (isModalOpen()) {
453:     if (e.code === 'Escape') {
454:       if (!el.screenHow.classList.contains('hidden')) closeHow();
455:       else closeArcade();
456:     }
457:     return;
458:   }
459:   if (state === 'title') {
460:     if (e.code === 'Enter' || e.code === 'Space') { sfx.ui(); newMatch('2p', titleChars); }
461:     return;
462:   }
463:   if (state === 'matchEnd') {
464:     if (endShown && (e.code === 'Enter' || e.code === 'Space')) rematch();
465:     return;
466:   }
467:   if (e.code === 'Escape') {
468:     if (paused) pauseGame(false);
469:     else pauseGame(true);
470:     return;
471:   }
472:   if (e.code === 'KeyM') { setMuted(!profile.muted); return; }
473:   if (paused) return;
474: 
475:   const pk = playerForKey(e.code);
476:   if (!pk) return;
477:   const p = players[pk.i];
478:   if (!p) return;
479:   if (pk.action === 'jump') queueJump(p);
480:   else if (pk.action === 'throw' && state === 'play') requestThrow(p);
481: }
482: 
483: function onKeyUp(e) {
484:   keys.delete(e.code);
485:   const pk = playerForKey(e.code);
486:   if (!pk) return;
487:   const p = players[pk.i];
488:   if (!p) return;
489:   if (pk.action === 'throw') releaseThrowInput(p);
490:   if (pk.action === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
491: }
492: 
493: function bindTouch() {
494:   document.querySelectorAll('.tbtn[data-act]').forEach(btn => {
495:     const pad = btn.closest('.pad');
496:     const pIdx = Number(pad.dataset.player);
497:     const act = btn.dataset.act;
498:     const down = e => {
499:       e.preventDefault();
500:       ensureAudio();
501:       if (state !== 'play' && state !== 'title') return;
502:       if (paused) return;
503:       btn.classList.add('pressed');
504:       pointerOwners.set(e.pointerId, { pIdx, act, btn });
505:       try { btn.setPointerCapture?.(e.pointerId); } catch {}
506:       const p = players[pIdx];
507:       if (!p) return;
508:       if (act === 'jump') queueJump(p);
509:       if (act === 'throw') {
510:         const moving = Math.abs(getInputDir(p)) > 0.15;
511:         requestThrow(p);
512:         if (!moving) setTimeout(() => releaseThrowInput(p), 90);
513:       }
514:     };
515:     const up = e => {
516:       const own = pointerOwners.get(e.pointerId);
517:       if (!own || own.pIdx !== pIdx) return;
518:       pointerOwners.delete(e.pointerId);
519:       btn.classList.remove('pressed');
520:       const p = players[pIdx];
521:       if (!p) return;
522:       if (act === 'throw') releaseThrowInput(p);
523:       if (act === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
524:     };
525:     btn.addEventListener('pointerdown', down);
526:     btn.addEventListener('pointerup', up);
527:     btn.addEventListener('pointercancel', up);
528:     btn.addEventListener('lostpointercapture', up);
529:     btn.addEventListener('contextmenu', e => e.preventDefault());
530:   });
531: }
532: 
533: /* ------------------------------ virtual joysticks ------------------------------ */
534: function bindJoysticks() {
535:   joysticks.length = 0;
536:   document.querySelectorAll('#touch .joystick').forEach(joyEl => {
537:     const pad = joyEl.closest('.pad');
538:     const pIdx = Number(pad.dataset.player);
539:     const base = joyEl.querySelector('.stick-base');
540:     const knob = joyEl.querySelector('.stick-knob');
541:     const j = { el: joyEl, knob, pIdx, pointerId: null, max: 1, jumpLatch: false };
542:     joysticks.push(j);
543: 
544:     const centerOf = () => {
545:       const r = base.getBoundingClientRect();
546:       const bounds = joyEl.getBoundingClientRect();
547:       const x = r.left + r.width / 2;
548:       const y = r.top + r.height / 2;
549:       // Anchor the knob to the base's measured center, not an assumed 50% of
550:       // its parent. This stays centered if the base and joystick ever diverge.
551:       knob.style.left = `${((x - bounds.left) / bounds.width) * 100}%`;
552:       knob.style.top = `${((y - bounds.top) / bounds.height) * 100}%`;
553:       j.max = Math.max(1, Math.min(r.width, r.height) * 0.3);
554:       return { x, y };
555:     };
556:     j.centerKnob = () => {
557:       centerOf();
558:       knob.style.transform = 'translate(-50%, -50%)';
559:     };
560:     const setAxis = (dx, dy) => {
561:       const raw = Math.hypot(dx, dy);
562:       const scale = raw > j.max ? j.max / raw : 1;
563:       const kx = dx * scale, ky = dy * scale;
564:       knob.style.transform = `translate(-50%, -50%) translate(${kx}px, ${ky}px)`;
565:       const x = clamp(kx / j.max, -1, 1);
566:       const dead = 0.16;
567:       touchAxes[pIdx] = Math.sign(x) * clamp((Math.abs(x) - dead) / (1 - dead), 0, 1);
568:       // drop through platforms on downward flick
569:       if (ky > j.max * 0.5) {
570:         const pp = players[pIdx];
571:         if (pp) {
572:           pp.dropThrough = 0.25;
573:           if (pp.onGround && pp.y < floorY - 1) { pp.vy = 120 * S; pp.onGround = false; }
574:         }
575:       }
576:       // jump on upward flick
577:       if (ky < -j.max * 0.5 && !j.jumpLatch) {
578:         j.jumpLatch = true;
579:         const p = players[pIdx];
580:         if (p) queueJump(p);
581:       }
582:       if (ky > -j.max * 0.25) j.jumpLatch = false;
583:     };
584:     const release = e => {
585:       if (j.pointerId === null) return;
586:       if (e && e.pointerId !== undefined && e.pointerId !== j.pointerId) return;
587:       const p = players[pIdx];
