250: .joystick{
251:   position:relative;width:var(--joy);height:var(--joy);flex:0 0 auto;
252:   border-radius:50%;pointer-events:auto;touch-action:none;
253:   -webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none;
254: }
255: .stick-base{
256:   position:absolute;inset:0;border-radius:50%;
