285:   transition:transform .06s,background .06s;
286: }
287: .touch .actions .tbtn{width:var(--btn);flex:1 1 0;min-height:0}
288: .tbtn:active,.tbtn.pressed{transform:translateY(3px);box-shadow:0 1px 0 var(--ink);background:#fff}
