293: .pause-mini{
294:   position:absolute;right:max(13px,env(safe-area-inset-right));
295:   top:calc(max(10px,env(safe-area-inset-top)) + 122px);
296:   width:34px;height:30px;padding:0;border-radius:9px;font-size:11px;letter-spacing:.05em;
297:   pointer-events:auto;background:rgba(255,244,216,.9);z-index:31;
