301:   width:32px;height:32px;border-radius:50%;border:2.5px solid var(--ink);
302:   background:rgba(255,244,216,.9);z-index:56;line-height:1;
303:   display:flex;align-items:center;justify-content:center;box-shadow:0 3px 0 var(--ink);
304:   transition:background .15s ease,transform .08s ease;
305: }
